import { useState } from "react";

export function App() {
  const [status, setStatus] = useState("idle");
  return (
    <div>
      <button data-testid="noop-state" onClick={() => setStatus("fixed")}>No-op state update</button>
      <span data-testid="status">{status}</span>
    </div>
  );
}
